 public static Project Todo(){Project p=new Project{Name="lista_zadan"};p.Blocks.AddRange(new[]{B("window","Moja lista zadań","640","420","#f7f5ff"),B("ui_label","title","Co dzisiaj zrobisz?","30","20","560","45"),B("ui_set","title","FontSize","22"),B("ui_input","task","Nowe zadanie","30","85","370","35"),B("ui_button","add","Dodaj","425","83","180","40"),B("ui_listbox","tasks","Zbuduj własną aplikację|Wypróbuj bloczki","30","145","575","200"),B("ui_button","clear","Wyczyść listę","425","360","180","36"),Event("event_button","add",B("ui_get","task","zadanie"),B("ui_item","tasks","{zadanie}"),B("ui_clear","task"),B("ui_focus","task")),Event("event_button","clear",B("ui_clear","tasks"))});return p;}
 public static Project Notebook(){Project p=new Project{Name="notatnik"};p.Features["Pliki"]=true;p.Blocks.AddRange(new[]{B("window","Mój notatnik","680","460","#f1f3f9"),B("ui_label","title","Notatnik z bloczków","25","15","600","40"),B("ui_set","title","FontSize","20"),B("ui_textarea","editor","Napisz coś…","25","75","630","295"),B("ui_button","open","Otwórz plik","25","395","180","40"),B("ui_button","save","Zapisz plik","225","395","180","40"),Event("event_button","open",B("file_open","plik"),ValidPath(B("file_read","{plik}","zawartosc"),B("ui_text","editor","{zawartosc}"))),Event("event_button","save",B("file_save","plik","notatka.txt"),ValidPath(B("ui_get","editor","zawartosc"),B("file_write","{plik}","{zawartosc}")))});return p;}
